package com.campusradar.accountdata;

import com.campusradar.common.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Component;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;
import static com.campusradar.common.SqlRows.map;

/** Only these explicit private projections may cross a backup boundary. */
@Component
public class PrivateSnapshot {
    private final SqlRows rows;private final Clock clock;private final TransactionTemplate snapshot;
    public record Table(String name,List<String> columns){}
    private static Table table(String name,String columns){return new Table(name,List.of(("id,version,created_at,updated_at,"+columns).split(",")));}
    static final List<Table> TABLES=List.of(
        table("resumes","file_id,name,sequence,is_default,text_content,extraction_state"),
        table("applications","job_id,resume_id,stage,sort_key,notes,applied_at,closed_reason,closed_at,archived_at"),
        table("application_stage_events","application_id,operation_id,from_stage,to_stage,result_board_version,old_closed_reason,old_closed_at,old_applied_at,old_sort_key,new_sort_key,old_before_id,old_after_id,result_version,occurred_at,undone"),
        table("interview_rounds","application_id,title,round_type,sequence,mode,status,starts_at,ends_at,timezone,location,meeting_url"),
        table("interview_reviews","round_id,recording_file_id,transcript,notes,self_score"),
        table("calendar_events","application_id,round_id,title,kind,starts_at,ends_at,timezone,location,meeting_url,notes,status"),
        table("chapter_progress","chapter_id,completed,note,chapter_version"),table("question_progress","question_id,mastery,is_wrong,note"),
        table("mock_sessions","role,company_id,duration_seconds,remaining_seconds,state,timer_started_at,report"),
        table("mock_answers","session_id,question_id,sequence,prompt_snapshot,reference_snapshot,answer_text,self_score"),
        table("plan_tasks","title,status,due_at,notes,milestone,sort_order,generation_key"),
        table("offers","application_id,company_name,title,city,base_monthly_minor,salary_months,bonus_minor,equity_note,benefits,expires_at,status,scores"),
        table("offer_comparisons","offer_ids,weights"),table("favorites","target_type,target_id"),
        table("notifications","type,title,body,target_path,read_at,dedup_key"),
        table("subscriptions","name,conditions,in_app,email_enabled,enabled,last_scanned_at"),
        table("subscription_hits","subscription_id,job_id,job_version,notification_id")
    );
    private static final List<String> PROFILE=List.of("display_name","school","education","graduation_year","preferences","theme","timezone","onboarding_step","buddy_discoverable","avatar_file_id");
    private static final Set<String> JSON=Set.of("preferences","report","scores","offer_ids","weights","conditions");
    private static final Set<String> BOOL=Set.of("is_default","undone","completed","is_wrong","in_app","email_enabled","enabled","buddy_discoverable");
    public PrivateSnapshot(SqlRows rows,PlatformTransactionManager manager,Clock clock){this.rows=rows;this.clock=clock;this.snapshot=new TransactionTemplate(manager);snapshot.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);}
    public record Captured(Map<String,Object> data,List<Map<String,Object>> files,Map<String,Map<String,Object>> storage,int revision){}
    public Captured capture(String owner){return snapshot.execute(status->{var p=Map.of("u",owner);var ownerRow=rows.one("SELECT status,data_operation,data_revision FROM users WHERE id=:u FOR UPDATE",p,Set.of(),Set.of());if(!"ACTIVE".equals(ownerRow.get("status"))||!"IDLE".equals(ownerRow.get("dataOperation")))throw new ApiProblem(409,"DATA_LOCKED","账号正在执行数据操作，请稍后重试导出。");var profile=rows.one("SELECT "+String.join(",",PROFILE)+" FROM users WHERE id=:u",p,JSON,BOOL);var tables=new LinkedHashMap<String,Object>();for(var table:TABLES){var data=rows.query("SELECT "+String.join(",",table.columns())+" FROM "+table.name()+" WHERE user_id=:u ORDER BY id",p,JSON,BOOL);if(table.name().equals("mock_sessions"))for(var s:data)if("ACTIVE".equals(s.get("state"))&&s.get("timerStartedAt")!=null){long elapsed=Math.max(0,Duration.between(Instant.parse(s.get("timerStartedAt").toString()),clock.instant()).getSeconds());s.put("remainingSeconds",Math.max(0,((Number)s.get("remainingSeconds")).longValue()-elapsed));s.put("timerStartedAt",clock.instant().toString());}for(var r:data)for(String key:List.of("sortKey","oldSortKey","newSortKey"))if(r.get(key) instanceof java.math.BigDecimal decimal)r.put(key,decimal.toPlainString());tables.put(table.name(),data);}
        var files=rows.query("SELECT id,purpose,original_name AS name,mime_type,size_bytes,sha256 FROM files WHERE user_id=:u AND purpose<>'BACKUP' AND state='READY' ORDER BY id",p);var physical=new HashMap<String,Map<String,Object>>();for(var f:rows.query("SELECT id,storage_key,size_bytes,sha256 FROM files WHERE user_id=:u AND purpose<>'BACKUP' AND state='READY'",p))physical.put(f.get("id").toString(),f);return new Captured(map("profile",profile,"tables",tables),files,physical,((Number)ownerRow.get("dataRevision")).intValue());});}
    @SuppressWarnings("unchecked") static Map<String,Object> tables(BackupCodec.Archive archive){return (Map<String,Object>)archive.data().get("tables");}
    @SuppressWarnings("unchecked") static List<Map<String,Object>> records(BackupCodec.Archive archive,String name){return (List<Map<String,Object>>)tables(archive).get(name);}
    public int recordCount(BackupCodec.Archive archive){return TABLES.stream().mapToInt(t->records(archive,t.name()).size()).sum();}
    @SuppressWarnings("unchecked") public List<String> validate(String owner,BackupCodec.Archive archive){var issues=new ArrayList<String>();try{
        if(!archive.data().keySet().equals(Set.of("profile","tables")))throw new IllegalArgumentException();var profile=(Map<String,Object>)archive.data().get("profile");if(!profile.keySet().equals(new HashSet<>(PROFILE.stream().map(SqlRows::camel).toList())))throw new IllegalArgumentException();var tables=tables(archive);if(!tables.keySet().equals(new HashSet<>(TABLES.stream().map(Table::name).toList())))throw new IllegalArgumentException();
        var ids=new HashMap<String,Set<String>>();int count=0;for(var table:TABLES){var found=new HashSet<String>();for(var row:records(archive,table.name())){if(!row.keySet().equals(new HashSet<>(table.columns().stream().map(SqlRows::camel).toList())))throw new IllegalArgumentException();String id=row.get("id").toString();UUID.fromString(id);if(!found.add(id))throw new IllegalArgumentException();if(rows.db.queryForObject("SELECT COUNT(*) FROM "+table.name()+" WHERE id=:id AND user_id<>:u",map("id",id,"u",owner),Integer.class)>0)issues.add("备份记录标识已被其他账号占用。");if(++count>20000)throw new IllegalArgumentException();}ids.put(table.name(),found);}
        var fileIds=new HashSet<String>();var filePurposes=new HashMap<String,String>();for(Object f:(List<?>)archive.manifest().get("files")){var file=(Map<String,Object>)f;if(!file.keySet().equals(Set.of("id","purpose","name","mimeType","sizeBytes","sha256"))||!Set.of("RESUME","RECORDING","AVATAR").contains(file.get("purpose"))||!(file.get("name") instanceof String name)||name.isBlank()||name.length()>255||!(file.get("mimeType") instanceof String mime)||mime.isBlank()||mime.length()>100||!(file.get("sha256") instanceof String hash)||!hash.matches("[a-f0-9]{64}")||((Number)file.get("sizeBytes")).longValue()<1||((Number)file.get("sizeBytes")).longValue()>BackupCodec.MAX_ARCHIVE)throw new IllegalArgumentException();String fileId=file.get("id").toString();UUID.fromString(fileId);if(!fileIds.add(fileId))throw new IllegalArgumentException();filePurposes.put(fileId,file.get("purpose").toString());if(!Boolean.TRUE.equals(archive.manifest().get("includeFiles"))&&rows.db.queryForObject("SELECT COUNT(*) FROM files WHERE user_id=:u AND id=:id AND state='READY' AND purpose=:purpose AND mime_type=:mime AND size_bytes=:size AND sha256=:hash",map("u",owner,"id",file.get("id"),"size",file.get("sizeBytes"),"hash",file.get("sha256"),"purpose",file.get("purpose"),"mime",file.get("mimeType")),Integer.class)!=1)issues.add("不含原件的备份缺少可复用文件："+file.get("name"));}ids.put("files",fileIds);
        if(profile.get("avatarFileId")!=null&&!"AVATAR".equals(filePurposes.get(profile.get("avatarFileId"))))issues.add("头像原件缺失或用途不符。");for(var row:records(archive,"resumes"))if(!"RESUME".equals(filePurposes.get(row.get("fileId"))))issues.add("简历原件缺失或用途不符。");for(var row:records(archive,"interview_reviews"))if(row.get("recordingFileId")!=null&&!"RECORDING".equals(filePurposes.get(row.get("recordingFileId"))))issues.add("录音原件缺失或用途不符。");
        for(var ref:List.of(new Ref("resumes","fileId","files"),new Ref("applications","resumeId","resumes"),new Ref("application_stage_events","applicationId","applications"),new Ref("interview_rounds","applicationId","applications"),new Ref("interview_reviews","roundId","interview_rounds"),new Ref("interview_reviews","recordingFileId","files"),new Ref("calendar_events","applicationId","applications"),new Ref("calendar_events","roundId","interview_rounds"),new Ref("mock_answers","sessionId","mock_sessions"),new Ref("offers","applicationId","applications"),new Ref("subscription_hits","subscriptionId","subscriptions"),new Ref("subscription_hits","notificationId","notifications")))for(var row:records(archive,ref.table()))if(row.get(ref.field())!=null&&!ids.get(ref.target()).contains(row.get(ref.field()).toString()))issues.add("私人关联缺失："+ref.table()+"."+ref.field());
        for(var ref:List.of(new Ref("applications","jobId","jobs"),new Ref("chapter_progress","chapterId","chapters"),new Ref("question_progress","questionId","questions"),new Ref("mock_answers","questionId","questions"),new Ref("mock_sessions","companyId","companies"),new Ref("subscription_hits","jobId","jobs")))for(var row:records(archive,ref.table()))if(row.get(ref.field())!=null&&rows.db.queryForObject("SELECT COUNT(*) FROM "+ref.target()+" WHERE id=:id",Map.of("id",row.get(ref.field())),Integer.class)!=1)issues.add("公开目标已不存在："+ref.table()+"."+ref.field());
        var rounds=new HashMap<String,Object>();for(var round:records(archive,"interview_rounds"))rounds.put(round.get("id").toString(),round.get("applicationId"));for(var event:records(archive,"calendar_events"))if(event.get("roundId")!=null&&!Objects.equals(event.get("applicationId"),rounds.get(event.get("roundId").toString())))issues.add("轮次日程的投递关联不一致。");
        for(var event:records(archive,"application_stage_events"))if(rows.db.queryForObject("SELECT COUNT(*) FROM application_stage_events WHERE operation_id=:id AND user_id<>:u",map("id",event.get("operationId"),"u",owner),Integer.class)>0)issues.add("投递操作标识已被其他账号占用。");
        for(var comparison:records(archive,"offer_comparisons"))for(Object id:(List<?>)comparison.get("offerIds"))if(!ids.get("offers").contains(id.toString()))issues.add("Offer 比较引用了清单之外的记录。");
    }catch(RuntimeException e){if(e instanceof org.springframework.dao.DataAccessException)throw e;issues.add("备份字段、类型、数量或关联结构无效。");}return issues.stream().distinct().limit(100).toList();}
    private record Ref(String table,String field,String target){}
    void clearPrivate(String owner){var p=Map.of("u",owner);rows.db.update("UPDATE users SET avatar_file_id=NULL WHERE id=:u",p);for(int i=TABLES.size()-1;i>=0;i--)rows.db.update("DELETE FROM "+TABLES.get(i).name()+" WHERE user_id=:u",p);}
    @SuppressWarnings("unchecked") void restore(String owner,BackupCodec.Archive archive,Map<String,String> fileMap){var p=Map.of("u",owner);var versions=new HashMap<String,Map<String,Integer>>();for(var table:TABLES){var saved=new HashMap<String,Integer>();for(var r:rows.query("SELECT id,version FROM "+table.name()+" WHERE user_id=:u",p))saved.put(r.get("id").toString(),((Number)r.get("version")).intValue());versions.put(table.name(),saved);}clearPrivate(owner);
        for(var table:TABLES)for(var old:records(archive,table.name())){var record=new LinkedHashMap<>(old);record.put("version",Math.max(versions.get(table.name()).getOrDefault(record.get("id").toString(),0),((Number)record.get("version")).intValue())+1);record.put("updatedAt",clock.instant().toString());if(table.name().equals("resumes"))record.put("fileId",fileMap.get(record.get("fileId")));if(table.name().equals("interview_reviews")&&record.get("recordingFileId")!=null)record.put("recordingFileId",fileMap.get(record.get("recordingFileId")));if(table.name().equals("application_stage_events")){record.put("undone",true);record.put("resultBoardVersion",0);}if(table.name().equals("mock_sessions")&&"ACTIVE".equals(record.get("state")))record.put("timerStartedAt",clock.instant().toString());var params=map("u",owner);for(String column:table.columns())params.put(SqlRows.camel(column),rows.value(column,record.get(SqlRows.camel(column)),JSON));String names=String.join(",",table.columns());String values=String.join(",",table.columns().stream().map(c->":"+SqlRows.camel(c)).toList());rows.db.update("INSERT INTO "+table.name()+"(user_id,"+names+") VALUES(:u,"+values+")",params);}
        var profile=new LinkedHashMap<>((Map<String,Object>)archive.data().get("profile"));if(profile.get("avatarFileId")!=null)profile.put("avatarFileId",fileMap.get(profile.get("avatarFileId")));var params=map("u",owner);for(String column:PROFILE)params.put(SqlRows.camel(column),rows.value(column,profile.get(SqlRows.camel(column)),JSON));rows.db.update("UPDATE users SET "+String.join(",",PROFILE.stream().map(c->c+"=:"+SqlRows.camel(c)).toList())+",version=version+1,data_revision=data_revision+1,board_version=board_version+1,data_operation='IDLE',updated_at=CURRENT_TIMESTAMP WHERE id=:u",params);
    }
}
